#!/usr/bin/env bash

# Wrapper script that is to be configured as htcondor's main executable file

htcondor_wrapper() {
    # helper to select the correct python executable
    _law_python() {
        command -v python &> /dev/null && python "$@" || python3 "$@"
    }

    #
    # detect variables
    #

    local shell_is_zsh="$( [ -z "${ZSH_VERSION}" ] && echo "false" || echo "true" )"
    local this_file="$( ${shell_is_zsh} && echo "${(%):-%x}" || echo "${BASH_SOURCE[0]}" )"
    local this_file_base="$( basename "${this_file}" )"

    # get the job number
    export LAW_HTCONDOR_JOB_NUMBER="${LAW_HTCONDOR_JOB_PROCESS}"
    if [ -z "${LAW_HTCONDOR_JOB_NUMBER}" ]; then
        >&2 echo "could not determine htcondor job number"
        return "1"
    fi
    # htcondor process numbers start at 0, law job numbers at 1, so increment
    ((LAW_HTCONDOR_JOB_NUMBER++))
    echo "running ${this_file_base} for job number ${LAW_HTCONDOR_JOB_NUMBER}"


    #
    # job argument definitons, depending on LAW_HTCONDOR_JOB_NUMBER
    #

    # definition
    local htcondor_job_arguments_map
    declare -A htcondor_job_arguments_map
    htcondor_job_arguments_map=(
        ['1']="columnflow.tasks.calibration CalibrateEvents  MA== 1 no LQ=="
        ['2']="columnflow.tasks.calibration CalibrateEvents  MQ== 1 no LQ=="
        ['3']="columnflow.tasks.calibration CalibrateEvents  Mg== 1 no LQ=="
        ['4']="columnflow.tasks.calibration CalibrateEvents  Mw== 1 no LQ=="
        ['5']="columnflow.tasks.calibration CalibrateEvents  NA== 1 no LQ=="
        ['6']="columnflow.tasks.calibration CalibrateEvents  NQ== 1 no LQ=="
        ['7']="columnflow.tasks.calibration CalibrateEvents  Ng== 1 no LQ=="
        ['8']="columnflow.tasks.calibration CalibrateEvents  Nw== 1 no LQ=="
        ['9']="columnflow.tasks.calibration CalibrateEvents  OA== 1 no LQ=="
        ['10']="columnflow.tasks.calibration CalibrateEvents  OQ== 1 no LQ=="
        ['11']="columnflow.tasks.calibration CalibrateEvents  MTA= 1 no LQ=="
        ['12']="columnflow.tasks.calibration CalibrateEvents  MTE= 1 no LQ=="
        ['13']="columnflow.tasks.calibration CalibrateEvents  MTI= 1 no LQ=="
        ['14']="columnflow.tasks.calibration CalibrateEvents  MTM= 1 no LQ=="
        ['15']="columnflow.tasks.calibration CalibrateEvents  MTQ= 1 no LQ=="
        ['16']="columnflow.tasks.calibration CalibrateEvents  MTU= 1 no LQ=="
        ['17']="columnflow.tasks.calibration CalibrateEvents  MTY= 1 no LQ=="
        ['18']="columnflow.tasks.calibration CalibrateEvents  MTc= 1 no LQ=="
        ['19']="columnflow.tasks.calibration CalibrateEvents  MTg= 1 no LQ=="
        ['20']="columnflow.tasks.calibration CalibrateEvents  MTk= 1 no LQ=="
        ['21']="columnflow.tasks.calibration CalibrateEvents  MjA= 1 no LQ=="
        ['22']="columnflow.tasks.calibration CalibrateEvents  MjE= 1 no LQ=="
        ['23']="columnflow.tasks.calibration CalibrateEvents  MjI= 1 no LQ=="
        ['24']="columnflow.tasks.calibration CalibrateEvents  MjM= 1 no LQ=="
        ['25']="columnflow.tasks.calibration CalibrateEvents  MjQ= 1 no LQ=="
        ['26']="columnflow.tasks.calibration CalibrateEvents  MjU= 1 no LQ=="
        ['27']="columnflow.tasks.calibration CalibrateEvents  MjY= 1 no LQ=="
        ['28']="columnflow.tasks.calibration CalibrateEvents  Mjc= 1 no LQ=="
        ['29']="columnflow.tasks.calibration CalibrateEvents  Mjg= 1 no LQ=="
        ['30']="columnflow.tasks.calibration CalibrateEvents  Mjk= 1 no LQ=="
        ['31']="columnflow.tasks.calibration CalibrateEvents  MzA= 1 no LQ=="
        ['32']="columnflow.tasks.calibration CalibrateEvents  MzE= 1 no LQ=="
        ['33']="columnflow.tasks.calibration CalibrateEvents  MzI= 1 no LQ=="
        ['34']="columnflow.tasks.calibration CalibrateEvents  MzM= 1 no LQ=="
        ['35']="columnflow.tasks.calibration CalibrateEvents  MzQ= 1 no LQ=="
        ['36']="columnflow.tasks.calibration CalibrateEvents  MzU= 1 no LQ=="
        ['37']="columnflow.tasks.calibration CalibrateEvents  MzY= 1 no LQ=="
        ['38']="columnflow.tasks.calibration CalibrateEvents  Mzc= 1 no LQ=="
        ['39']="columnflow.tasks.calibration CalibrateEvents  Mzg= 1 no LQ=="
        ['40']="columnflow.tasks.calibration CalibrateEvents  Mzk= 1 no LQ=="
        ['41']="columnflow.tasks.calibration CalibrateEvents  NDA= 1 no LQ=="
        ['42']="columnflow.tasks.calibration CalibrateEvents  NDE= 1 no LQ=="
        ['43']="columnflow.tasks.calibration CalibrateEvents  NDI= 1 no LQ=="
        ['44']="columnflow.tasks.calibration CalibrateEvents  NDM= 1 no LQ=="
        ['45']="columnflow.tasks.calibration CalibrateEvents  NDQ= 1 no LQ=="
        ['46']="columnflow.tasks.calibration CalibrateEvents  NDU= 1 no LQ=="
        ['47']="columnflow.tasks.calibration CalibrateEvents  NDY= 1 no LQ=="
        ['48']="columnflow.tasks.calibration CalibrateEvents  NDc= 1 no LQ=="
        ['49']="columnflow.tasks.calibration CalibrateEvents  NDg= 1 no LQ=="
        ['50']="columnflow.tasks.calibration CalibrateEvents  NDk= 1 no LQ=="
        ['51']="columnflow.tasks.calibration CalibrateEvents  NTA= 1 no LQ=="
        ['52']="columnflow.tasks.calibration CalibrateEvents  NTE= 1 no LQ=="
        ['53']="columnflow.tasks.calibration CalibrateEvents  NTI= 1 no LQ=="
        ['54']="columnflow.tasks.calibration CalibrateEvents  NTM= 1 no LQ=="
        ['55']="columnflow.tasks.calibration CalibrateEvents  NTQ= 1 no LQ=="
        ['56']="columnflow.tasks.calibration CalibrateEvents  NTU= 1 no LQ=="
        ['57']="columnflow.tasks.calibration CalibrateEvents  NTY= 1 no LQ=="
        ['58']="columnflow.tasks.calibration CalibrateEvents  NTc= 1 no LQ=="
        ['59']="columnflow.tasks.calibration CalibrateEvents  NTg= 1 no LQ=="
        ['60']="columnflow.tasks.calibration CalibrateEvents  NTk= 1 no LQ=="
        ['61']="columnflow.tasks.calibration CalibrateEvents  NjA= 1 no LQ=="
        ['62']="columnflow.tasks.calibration CalibrateEvents  NjE= 1 no LQ=="
        ['63']="columnflow.tasks.calibration CalibrateEvents  NjI= 1 no LQ=="
        ['64']="columnflow.tasks.calibration CalibrateEvents  NjM= 1 no LQ=="
        ['65']="columnflow.tasks.calibration CalibrateEvents  NjQ= 1 no LQ=="
        ['66']="columnflow.tasks.calibration CalibrateEvents  NjU= 1 no LQ=="
        ['67']="columnflow.tasks.calibration CalibrateEvents  NjY= 1 no LQ=="
        ['68']="columnflow.tasks.calibration CalibrateEvents  Njc= 1 no LQ=="
        ['69']="columnflow.tasks.calibration CalibrateEvents  Njg= 1 no LQ=="
        ['70']="columnflow.tasks.calibration CalibrateEvents  Njk= 1 no LQ=="
        ['71']="columnflow.tasks.calibration CalibrateEvents  NzA= 1 no LQ=="
        ['72']="columnflow.tasks.calibration CalibrateEvents  NzE= 1 no LQ=="
        ['73']="columnflow.tasks.calibration CalibrateEvents  NzI= 1 no LQ=="
        ['74']="columnflow.tasks.calibration CalibrateEvents  NzM= 1 no LQ=="
        ['75']="columnflow.tasks.calibration CalibrateEvents  NzQ= 1 no LQ=="
        ['76']="columnflow.tasks.calibration CalibrateEvents  NzU= 1 no LQ=="
        ['77']="columnflow.tasks.calibration CalibrateEvents  NzY= 1 no LQ=="
        ['78']="columnflow.tasks.calibration CalibrateEvents  Nzc= 1 no LQ=="
        ['79']="columnflow.tasks.calibration CalibrateEvents  Nzg= 1 no LQ=="
        ['80']="columnflow.tasks.calibration CalibrateEvents  Nzk= 1 no LQ=="
        ['81']="columnflow.tasks.calibration CalibrateEvents  ODA= 1 no LQ=="
        ['82']="columnflow.tasks.calibration CalibrateEvents  ODE= 1 no LQ=="
        ['83']="columnflow.tasks.calibration CalibrateEvents  ODI= 1 no LQ=="
        ['84']="columnflow.tasks.calibration CalibrateEvents  ODM= 1 no LQ=="
        ['85']="columnflow.tasks.calibration CalibrateEvents  ODQ= 1 no LQ=="
        ['86']="columnflow.tasks.calibration CalibrateEvents  ODU= 1 no LQ=="
        ['87']="columnflow.tasks.calibration CalibrateEvents  ODY= 1 no LQ=="
        ['88']="columnflow.tasks.calibration CalibrateEvents  ODc= 1 no LQ=="
        ['89']="columnflow.tasks.calibration CalibrateEvents  ODg= 1 no LQ=="
        ['90']="columnflow.tasks.calibration CalibrateEvents  ODk= 1 no LQ=="
        ['91']="columnflow.tasks.calibration CalibrateEvents  OTA= 1 no LQ=="
        ['92']="columnflow.tasks.calibration CalibrateEvents  OTE= 1 no LQ=="
        ['93']="columnflow.tasks.calibration CalibrateEvents  OTI= 1 no LQ=="
        ['94']="columnflow.tasks.calibration CalibrateEvents  OTM= 1 no LQ=="
        ['95']="columnflow.tasks.calibration CalibrateEvents  OTQ= 1 no LQ=="
    )

    # pick
    local htcondor_job_arguments="${htcondor_job_arguments_map[${LAW_HTCONDOR_JOB_NUMBER}]}"
    if [ -z "${htcondor_job_arguments}" ]; then
        >&2 echo "empty htcondor job arguments for LAW_HTCONDOR_JOB_NUMBER ${LAW_HTCONDOR_JOB_NUMBER}"
        return "3"
    fi


    #
    # variable rendering
    #

    # check variables
    local render_variables=""
    if [ -z "${render_variables}" ]; then
        >&2 echo "empty render variables"
        return "4"
    fi

    # decode
    render_variables="$( echo "${render_variables}" | base64 --decode )"

    # check files to render
    local input_files_render=( law_job_60abdeb487.sh remote_bootstrap_11d1b65a98.sh )
    if [ "${#input_files_render[@]}" == "0" ]; then
        >&2 echo "received empty input files for rendering for LAW_HTCONDOR_JOB_NUMBER ${LAW_HTCONDOR_JOB_NUMBER}"
        return "5"
    fi

    # render files
    local input_file_render
    for input_file_render in ${input_files_render[@]}; do
        # skip if the file refers to _this_ one
        local input_file_render_base="$( basename "${input_file_render}" )"
        [ "${input_file_render_base}" = "${this_file_base}" ] && continue
        # render
        echo "render ${input_file_render}"
        cat > _render.py << EOT
import re
repl = ${render_variables}
repl['input_files_render'] = ''
repl['file_postfix'] = '${file_postfix}' or repl.get('file_postfix', '')
repl['log_file'] = ''
content = open('${input_file_render}', 'r').read()
content = re.sub(r'\{\{(\w+)\}\}', lambda m: repl.get(m.group(1), ''), content)
open('${input_file_render_base}', 'w').write(content)
EOT
        _law_python _render.py
        local render_ret="$?"
        rm -f _render.py
        # handle rendering errors
        if [ "${render_ret}" != "0" ]; then
            >&2 echo "input file rendering failed with code ${render_ret}"
            return "6"
        fi
    done


    #
    # run the actual job file
    #

    # check the job file
    local job_file="law_job_60abdeb487.sh"
    if [ ! -f "${job_file}" ]; then
        >&2 echo "job file '${job_file}' does not exist"
        return "7"
    fi

    # helper to print a banner
    banner() {
        local msg="$1"

        echo
        echo "================================================================================"
        echo "=== ${msg}"
        echo "================================================================================"
        echo
    }

    # debugging: print its contents
    # echo "=== content of job file '${job_file}'"
    # echo
    # cat "${job_file}"
    # echo
    # echo "=== end of job file content"

    # run it
    banner "Start of law job"

    local job_ret
    bash "${job_file}" ${htcondor_job_arguments}
    job_ret="$?"

    banner "End of law job"

    return "${job_ret}"
}

action() {
    # arguments: file_postfix, log_file
    local file_postfix="$1"
    local log_file="$2"

    # create log directory
    if [ ! -z "${log_file}" ]; then
        local log_dir="$( dirname "${log_file}" )"
        [ ! -d "${log_dir}" ] && mkdir -p "${log_dir}"
    fi

    # run the wrapper function
    if [ -z "${log_file}" ]; then
        htcondor_wrapper "$@"
    elif command -v tee &> /dev/null; then
        set -o pipefail
        echo "---" >> "${log_file}"
        htcondor_wrapper "$@" 2>&1 | tee -a "${log_file}"
    else
        echo "---" >> "${log_file}"
        htcondor_wrapper "$@" &>> "${log_file}"
    fi
}

action "$@"
